package com.zomiggy.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="orders") public class Order { @Id private String id; @ManyToOne(optional=false,fetch=FetchType.LAZY) private User user; @Column(nullable=false) private String status="Processing"; @Column(nullable=false) private String paymentMethod; @Column(nullable=false) private String paymentStatus; private String splitPaymentId; @Column(nullable=false) private int total; @Column(nullable=false) private String deliveryAddress; private Double deliveryLatitude; private Double deliveryLongitude; private Instant createdAt=Instant.now(); @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) private List<OrderItem> items=new ArrayList<>(); protected Order(){} public Order(String id,User user,String paymentMethod,int total,String address,Double latitude,Double longitude){this.id=id;this.user=user;this.paymentMethod=paymentMethod;this.paymentStatus=paymentMethod.equals("COD")?"PENDING":"PAID";this.total=total;this.deliveryAddress=address;this.deliveryLatitude=latitude;this.deliveryLongitude=longitude;} public void setSplitPaymentId(String value){splitPaymentId=value;} public void addItem(OrderItem item){items.add(item);item.setOrder(this);} public String getId(){return id;} public User getUser(){return user;} public String getStatus(){return status;} public String getPaymentMethod(){return paymentMethod;} public String getPaymentStatus(){return paymentStatus;} public String getSplitPaymentId(){return splitPaymentId;} public int getTotal(){return total;} public String getDeliveryAddress(){return deliveryAddress;} public Double getDeliveryLatitude(){return deliveryLatitude;} public Double getDeliveryLongitude(){return deliveryLongitude;} public Instant getCreatedAt(){return createdAt;} public List<OrderItem> getItems(){return items;} }